input.command:
sed -i 's/{ echo "bad time: $x (expected HH:MM)" >\&2; exit 1; }/{ echo "bad time: $x (expected HH:MM)" >\&2; exit 2; }/' src/book.sh && cat > spec/book_time.spec.sh <<'EOF'
#!/bin/bash
fail=0
t=$(mktemp); printf '# h\n' > "$t"
BOOKINGS=$t bash src/book.sh aoi 2026-01-05 9am 10:00 x >/dev/null 2>&1; [ $? = 2 ] || { echo "9am: expected exit 2"; fail=1; }
BOOKINGS=$t bash src/book.sh aoi 2026-01-05 10:00 10am x >/dev/null 2>&1; [ $? = 2 ] || { echo "end 10am: expected exit 2"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 0 ] || { echo "a rejected booking was stored"; fail=1; }
rm -f "$t"; exit $fail
EOF
bash spec/book_time.spec.sh; echo "spec exit=$?"; git diff; bash tools/check; echo "check=$?"; bash tools/lint; echo "lint=$?"

